        // The HLOD definition loader (see differential/wrap_w3d_hlod.cpp),
        // also linked before upstream_w3d. hlod.cpp as a whole cannot be
        // linked here (HLodClass, the render object, needs the renderer), so
        // two segments of its text are taken VERBATIM, each delimited by
        // markers that must occur once: (1) OUT_DIR/w3d_gen/hlod_proxy.h,
        // ProxyRecordClass and ProxyArrayClass (defined in hlod.cpp, not in
        // a header; the wrapper reads them too); (2) hlod_def.cpp, every
        // HLodDefClass and SubObjectArrayClass function (from the "HLodDef
        // Implementation" comment to the comment of HLodClass's first
        // constructor). Left out: HLodLoaderClass::Load_W3D and
        // HLodPrototypeClass::Create (the asset-manager wrapper around
        // Load_W3D, which constructs an HLodClass) and HLodClass. The copy is
        // preceded by what hlod.cpp got from windows.h (TRUE, FALSE,
        // _strdup = strdup, and a declaration of lstrcpyn, which only the
