        // - w3d_gen/collection_def.h: the CollectionDefClass class (defined
        //   in collect.cpp, not a header), after the headers collect.cpp's
        //   own includes give it; collection_def.cpp: its constructor,
        //   destructor, Free, Get_Name and Load (contiguous in collect.cpp,
