        agg_cpp.extend_from_slice(b"void\n");
        agg_cpp.extend(agg_fn(b"AggregateDefClass::Free_Subobject_List (void)\n"));
        let load_a = once_in(&agg_text, b"WW3DErrorType\nAggregateDefClass::Load_W3D (ChunkLoadClass &chunk_load)", "agg_def.cpp");
        let save = once_in(&agg_text, b"WW3DErrorType\nAggregateDefClass::Save_W3D (ChunkSaveClass &chunk_save)", "agg_def.cpp");
        let load_b = (0..save).rev().find(|&i| agg_text[i..].starts_with(b"\n////////")).expect("comment of Save_W3D");
