            let mut ms = cc::Build::new();
            base(&mut ms);
            ms.include(&shim_energy)
                .include(&shim)
                .include(up.join("GameEngine/Include"))
                .include(up.join("Libraries/Include"))
                .include(ww.join("WWMath"))
                .include(ww.join("WWLib"))
