            // constructor to its end, PopupPlayerInfo.cpp's BattleHonorTooltip, rowsToSkip, ResetBattleHonorInsertion
            // and InsertBattleHonor (to populateBattleHonors), SkirmishGameOptionsMenu.cpp's populateSkirmishBattleHonors
            // (to its end), ScoreScreen.cpp's isSlotLocalAlly and updateSkirmishBattleHonors (to updateMPBattleHonors)
            // and updateChallengeMedals (to CheckForApocalypse); and into battle_honors_tail.inc populatePlayerInfo's
            // skirmish block (to its internet block). Each anchor must occur once. Built on the user preferences' cut
            // (the REAL UserPreferences) and the REAL AsciiString, under names of their own.
            let bh_once = |text: &str, m: &str, what: &str| {
                assert_eq!(text.matches(m).count(), 1, "{what}: {m:?} must occur once");
                text.find(m).expect("anchor")
            };
            let bh_cut = |text: &str, from: &str, to: Option<&str>, what: &str| -> String {
                let i = bh_once(text, from, what);
                let j = match to {
                    Some(t) => bh_once(text, t, what),
                    None => text.len(),
                };
                assert!(i < j, "{what}: the cut's end before its start");
                text[i..j].to_string()
            };
            let menus = up.join("GameEngine/Source/GameClient/GUI/GUICallbacks/Menus");
            let sbh_h = read_upstream(up.join("GameEngine/Include/Common/SkirmishBattleHonors.h"));
            let sbh_c = read_upstream(up.join("GameEngine/Source/Common/SkirmishBattleHonors.cpp"));
