            std::fs::write(bh_gen.join("battle_honors_cut.inc"), format!("/* generated by build.rs: pieces of upstream, verbatim (see differential/wrap_battle_honors.cpp) */\n{}\n", bh_text.join("\n"))).expect("write battle_honors_cut.inc");
            std::fs::write(bh_gen.join("battle_honors_tail.inc"), format!("/* generated by build.rs: ScoreScreen.cpp's populatePlayerInfo skirmish block, verbatim */\n{bh_tail}\n")).expect("write battle_honors_tail.inc");
