        // verbatim members of AIUpdate.cpp, so that the AI drives real locomotors along real paths. Generated into OUT_DIR/ai_gen,
        // each cut's markers asserted to occur once:
        // - ai_defs.h: AIUpdate.h's `FAST_AS_POSSIBLE` .. the locomotor template typedefs, AI.h's AttitudeType line,
        //   UpdateModule.h's UpdateSleepTime and UPDATE_SLEEP, PartitionManager.h's DistanceCalculationType;
        // - ai_update_members.inc: AIUpdateInterface's data members (`m_priorWaypointID` .. `m_fixLocoInPostProcess`), for the
        //   wrapper's declaration of the class (the real one needs the whole AI);
        // - ai_update_a2.inc: AIUpdate.cpp's `#define SLEEPY_AI`, its members of batch A2, each from its signature to the end of
        //   its body, and AIUpdateModuleData::findLocomotorTemplateVector;
        // - ai_pathfinder_a2.inc: AIPathfind.cpp's chooseBestLocomotorForPosition and validLocomotorSurfacesForCellType.
