                let i = once(text, file, inner);
                let a = text[..i].rfind("enum").unwrap_or_else(|| panic!("{file}: an enum before {inner:?}"));
                let rel = text[i..].find("};").unwrap_or_else(|| panic!("{file}: `}};` after {inner:?}"));
