            let mut gb = cc::Build::new();
            base(&mut gb);
            gb.compiler("clang++")
                .flag("-fms-extensions")
                .include(&gen)
                .include(up.join("Libraries/Include"))
                .include(&shim)
                .file(dif.join("wrap_ai_group.cpp"));
            gb.compile("upstream_ai_group");
            println!("cargo:rerun-if-changed=differential/wrap_ai_group.cpp");
            println!("cargo:rerun-if-changed=upstream/GeneralsMD/Code/GameEngine/Source/GameLogic/AI/AIGroup.cpp");
            println!("cargo:rerun-if-changed=upstream/GeneralsMD/Code/GameEngine/Source/GameClient/Line2D.cpp");
            // batch A28: the AI player (differential/wrap_ai_player.cpp): GameCommon.h's intrusive lists (with the member pointer
            // MSVC lets them leave implicit, as below), AIPlayer.h's classes and AIPlayer.cpp from SUPPLY_CENTER_CLOSE_DIST, verbatim,
            // over a world of the wrapper's own. -ftrivial-auto-var-init=zero: onUnitProduced reads `supplyTruck` unset when no
            // work order took the unit (zero: false, as the Rust).
            let gen_ap = out_dir.join("ai_player_gen");
            std::fs::create_dir_all(&gen_ap).expect("ai_player_gen");
            let gc = rd(engine.join("Include/Common/GameCommon.h"));
            let d0 = once(&gc, "GameCommon.h", "#define MAKE_DLINK_HEAD(OBJCLASS, LISTNAME)");
            let d1 = once(&gc, "GameCommon.h", "class DLINK_ITERATOR");
            let d1 = gc[d1..].find("\n};").expect("DLINK_ITERATOR's end") + d1 + 3;
            let head = "return DLINK_ITERATOR<OBJCLASS>(m_dlinkhead_##LISTNAME.m_head, OBJCLASS::dlink_next_##LISTNAME);";
            let dl = &gc[d0..d1];
            assert_eq!(dl.matches(head).count(), 1, "GameCommon.h: the iterator's head");
            let dl = dl.replace(head, "return DLINK_ITERATOR<OBJCLASS>(m_dlinkhead_##LISTNAME.m_head, &OBJCLASS::dlink_next_##LISTNAME);");
            std::fs::write(gen_ap.join("ai_player_dlink.inc"), format!("/* generated by build.rs: GameCommon.h's DLINK macros and iterator (batch A28) */\n{dl}\n"))
                .expect("write ai_player_dlink.inc");
            let aph = rd(engine.join("Include/GameLogic/AIPlayer.h"));
            let h0 = once(&aph, "AIPlayer.h", "enum { INVALID_SKILLSET_SELECTION");
            let h1 = aph.rfind("};").expect("AIPlayer.h's last class") + 2;
            std::fs::write(gen_ap.join("ai_player_h.inc"), format!("/* generated by build.rs: AIPlayer.h's classes, verbatim (batch A28) */\n{}\n", &aph[h0..h1]))
                .expect("write ai_player_h.inc");
            let apc = rd(engine.join("Source/GameLogic/AI/AIPlayer.cpp"));
            let c0 = once(&apc, "AIPlayer.cpp", "#define SUPPLY_CENTER_CLOSE_DIST");
            std::fs::write(gen_ap.join("ai_player_cpp.inc"), format!("/* generated by build.rs: AIPlayer.cpp from SUPPLY_CENTER_CLOSE_DIST, verbatim (batch A28) */\n{}\n", &apc[c0..]))
                .expect("write ai_player_cpp.inc");
            // batch A29: AISkirmishPlayer.h's class and AISkirmishPlayer.cpp from its constructor, verbatim
            let skh = rd(engine.join("Include/GameLogic/AISkirmishPlayer.h"));
            let k0 = once(&skh, "AISkirmishPlayer.h", "class AISkirmishPlayer : public AIPlayer");
            let k1 = skh.rfind("};").expect("AISkirmishPlayer.h's class") + 2;
            std::fs::write(gen_ap.join("ai_skirmish_player_h.inc"), format!("/* generated by build.rs: AISkirmishPlayer.h's class, verbatim (batch A29) */\n{}\n", &skh[k0..k1]))
                .expect("write ai_skirmish_player_h.inc");
            let skc = rd(engine.join("Source/GameLogic/AI/AISkirmishPlayer.cpp"));
            let s0 = once(&skc, "AISkirmishPlayer.cpp", "AISkirmishPlayer::AISkirmishPlayer( Player *p )");
            std::fs::write(
                gen_ap.join("ai_skirmish_player_cpp.inc"),
                format!("/* generated by build.rs: AISkirmishPlayer.cpp from its constructor, verbatim (batch A29) */\n{}\n", &skc[s0..]),
            )
            .expect("write ai_skirmish_player_cpp.inc");
            let mut pb = cc::Build::new();
            base(&mut pb);
            pb.compiler("clang++")
