                let last = "static Bool distCalcProc_BoundaryAndBoundary_3D(\n";
                let tail = "\treturn abDistSqr < maxDistSqr;\n}\n";
                assert_eq!(text.matches(first).count(), 1, "PartitionManager.cpp: distCalcProc_CenterAndCenter_2D's definition must occur once");
                assert_eq!(text.matches(last).count(), 1, "PartitionManager.cpp: distCalcProc_BoundaryAndBoundary_3D's definition must occur once");
                let at = text.find(first).expect("the first procedure");
                let at_last = text.find(last).expect("the last procedure");
                assert!(at < at_last, "PartitionManager.cpp: the distance procedures are in their order");
                let stop = at_last + text[at_last..].find(tail).expect("the end of the last procedure") + tail.len();
                std::fs::write(mod_gen.join("PartitionDist.inc"), format!("/* generated by build.rs: PartitionManager.cpp's distance procedures, verbatim */\n{}", &text[at..stop]))
                    .expect("write PartitionDist.inc");
